# Reference values from SaddlepointExpansions.jl for the MATLAB tests (test_spx.m). The cases are
# now generated by test/reference_values.jl of the Julia package, shared with the Python package,
# and this script only runs it: it activates the Julia package next to the MATLAB package
# (../../SaddlepointExpansions.jl) and copies the result to julia_reference.csv (same columns:
# case, quantity, order, value; the first part is the original case list, unchanged).
# Run from this folder:  julia julia_reference.jl
using Pkg
pkg = joinpath(@__DIR__, "..", "..", "SaddlepointExpansions.jl")
Pkg.activate(pkg)
Pkg.instantiate()
include(joinpath(pkg, "test", "reference_values.jl"))
cp(joinpath(pkg, "test", "reference_values.csv"), joinpath(@__DIR__, "julia_reference.csv"); force=true)
println("copied to ", joinpath(@__DIR__, "julia_reference.csv"))
